CREATE TABLE hub_email_drafts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,brand_id TEXT NOT NULL REFERENCES hub_brands(id),mailbox_id TEXT REFERENCES social_connections(id),lead_id TEXT REFERENCES hub_leads(id),reply_to_id TEXT,recipients TEXT NOT NULL,cc TEXT NOT NULL,bcc TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,attachments TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','discarded')),version INTEGER NOT NULL DEFAULT 1,client_key TEXT NOT NULL,payload_hash TEXT NOT NULL,created_by TEXT NOT NULL,updated_by TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(workspace_id,client_key));
CREATE INDEX hub_email_drafts_brand ON hub_email_drafts(workspace_id,brand_id,updated_at);
CREATE TABLE hub_email_messages(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,brand_id TEXT NOT NULL REFERENCES hub_brands(id),mailbox_id TEXT NOT NULL REFERENCES social_connections(id),provider_id TEXT NOT NULL,thread_id TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN ('incoming','outgoing')),sender TEXT NOT NULL,recipients TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,received_at INTEGER NOT NULL,UNIQUE(mailbox_id,provider_id));
CREATE INDEX hub_email_threads ON hub_email_messages(workspace_id,brand_id,thread_id,received_at);
